function updateAirlineSummary(root) {
  var sumEl = root.querySelector(".cus-ops-airline-summary");
  if (!sumEl) return;
  var cbs = root.querySelectorAll(".cus-ops-airline-cb");
  var n = cbs.length;
  var selN = 0;
  for (var i = 0; i < cbs.length; i++) {
    if (cbs[i].checked) selN++;
