  if (!n) {
    sumEl.textContent = __("No airlines");
    return;
  }
  if (!selN || selN === n) {
    sumEl.textContent = __("All airlines");
    return;
  }
  if (selN === 1) {
    for (var j = 0; j < cbs.length; j++) {
      if (cbs[j].checked) {
        var row = cbs[j].closest(".cus-ops-airline-cb-row");
        var sp = row && row.querySelector(".cus-ops-airline-lbl");
