          ban.style.display = "none";
          ban.textContent = "";
        }
      }
      populateAirlineFilter(root, d.airline_options || [], prevAir);
      root._afwLastMarkers = d.unloco_markers || [];
      root._afwLastRenderer = d.map_renderer || "";
      renderMap(root, root._afwLastMarkers, root._afwLastRenderer);
      renderAlerts(root, d.alert_summary || {}, d.alert_items || []);
    },
  });
}
var r = root_element;
r.querySelector(".afw-hub-refresh").addEventListener("click", refresh);
var st = r.querySelector(".cus-ops-filter-status");
if (st) {
  st.addEventListener("change", function () {
    populateUserFilter(root_element, getJobStatusFilter(root_element));
    populateAlertUserFilter(root_element, getJobStatusFilter(root_element));
    refresh();
  });
}
var fu = r.querySelector(".cus-ops-filter-user");
if (fu) {
  fu.addEventListener("change", function () {
    fu._cusOwnerTouched = true;
    refresh();
  });
}
var afu = r.querySelector(".cus-ops-filter-alert-user");
if (afu) {
  afu.addEventListener("change", function () {
    afu._cusAlertUserTouched = true;
    refresh();
  });
}
var arf = r.querySelector(".cus-ops-alerts-refresh");
if (arf) {
  arf.addEventListener("click", refresh);
}
var trf = r.querySelector(".cus-ops-filter-traffic");
if (trf) {
  trf.addEventListener("change", refresh);
}
bindAirlineDropdown(root_element);
populateUserFilter(root_element, getJobStatusFilter(root_element));
populateAlertUserFilter(root_element, getJobStatusFilter(root_element));
refresh();

style:
