.afw-hub-popup-stats {
  display: flex;
  flex-direction: column;
  gap: 0.28rem;
}
.afw-hub-popup-stat {
  font-size: 0.8125rem;
  line-height: 1.35;
  color: var(--ro-text, #333);
}
.afw-hub-popup-stat strong {
  font-weight: 600;
}

