	display: flex;
	align-items: center;
	gap: 8px;
	background: #f8f9fa;
	border-bottom: 1px solid #e9ecef;
}
.run-sheet-cards-panel-summary::-webkit-details-marker { display: none; }
.run-sheet-cards-panel-summary::before {
	content: "";
