  });
  var unasPanel = root.querySelector(".hv-ops-unassigned-panel");
  var unasWrap = root.querySelector(".hv-ops-unassigned-wrap");
  if (unasPanel) unasPanel.style.display = unas.length || (!q && (d.unassigned_jobs || 0)) ? "" : "none";
  if (unasWrap) {
    if (!unas.length) {
      unasWrap.innerHTML =
