    } else {
      unasWrap.innerHTML =
        '<table class="hv-ops-table"><thead><tr><th>' +
        __("Job") +
        "</th><th>" +
        __("Type") +
        "</th><th>" +
        __("Status") +
        "</th><th>" +
        __("SLA") +
        "</th><th>" +
        __("Owner") +
        "</th></tr></thead><tbody>" +
