              (r.sla_at_risk ? (r.sla_breached ? ", " : "") + r.sla_at_risk + " " + __("at risk") : "");
            return (
              "<tr><td>" +
              docLink(r.doctype || "HV Brands", r.name, r.title || r.name) +
