.route-container { display: flex; gap: 20px; margin: 20px 0; align-items: flex-start; }
.cards-sidebar { flex: 1; max-width: 320px; min-width: 0; }
/* Collapsible milestone/leg column (details/summary — no JS, always shows a control) */
