}
.log-ab-dash .log-ab-route-flag {
	font-size: 1.55rem; line-height: 1; flex-shrink: 0; margin-top: 0.08rem;
	font-family: "Segoe UI Emoji", "Apple Color Emoji", "Noto Color Emoji", sans-serif;
}
